const config=window.SUNDAR_CONFIG,demoData=window.SUNDAR_DEMO_DATA,phone=config.whatsappNumber,categories=demoData.categories,products=[...demoData.products];
let selected='All';
const filters=document.querySelector('#categoryFilters'),grid=document.querySelector('#productGrid'),designTitle=document.querySelector('#design-title');
const escapeHtml=value=>String(value).replace(/[&<>"']/g, char=>({"&":"&amp;","<":"&lt;",">":"&gt;",'"':"&quot;","'":"&#39;"}[char]));
const cropStyle=p=>{if(p.image)return `--image:url('${p.image}');background-size:contain;background-position:center`;const column=p.imageIndex%5,row=Math.floor(p.imageIndex/5);return `--image:url('${p.asset}');--image-x:${column*25}%;--image-y:${row*100}%`};
function renderFilters(){filters.innerHTML=categories.map(item=>`<button class="category-card ${item.category===selected?'active':''}" data-category="${item.category}" aria-pressed="${item.category===selected}"><span class="category-preview" style="${cropStyle(item)}"></span><span class="category-label"><span>${item.icon}</span><strong>${item.category}</strong></span></button>`).join('')}
function visibleProducts(){return selected==='All'?[...products.filter(p=>p.image),...categories.slice(1).flatMap(item=>products.filter(p=>!p.image&&p.category===item.category).slice(0,2))]:products.filter(p=>p.category===selected)}
function renderProducts(){const list=visibleProducts();designTitle.textContent=selected==='All'?'Popular from our workshop':`${selected} ideas`;grid.innerHTML=list.map(p=>`<article class="product-card" tabindex="0" data-id="${p.id}" aria-label="View ${escapeHtml(p.name)} and more ${escapeHtml(p.category)} ideas"><div class="product-image" style="${cropStyle(p)}"><span>View design</span></div><div class="product-body"><small>${escapeHtml(p.category)}</small><h3>${escapeHtml(p.name)}</h3><div class="product-meta"><span>${p.price}</span><span>${p.days}</span></div></div></article>`).join('')}
filters.addEventListener('click',e=>{const b=e.target.closest('[data-category]');if(!b)return;selected=b.dataset.category;renderFilters();renderProducts();document.querySelector('#designs').scrollIntoView({behavior:'smooth',block:'start'})});
document.querySelector('#showAll').onclick=()=>{selected='All';renderFilters();renderProducts()};
function openProduct(id){let original=products.find(p=>String(p.id)===String(id)),items=products.filter(p=>p.category===original.category),active=items.findIndex(p=>p.id===original.id),detail=document.querySelector('#productDetail');function renderDetail(){const p=items[active],msg=encodeURIComponent(`Hello Sundar Embroidery Works, I am interested in ${p.name} from your ${p.category} collection. Please share price and details.`);detail.innerHTML=`<div class="detail-main"><button class="gallery-arrow previous" aria-label="Previous design">‹</button><div class="detail-image" role="img" aria-label="${escapeHtml(p.name)}" style="${cropStyle(p)}"></div><button class="gallery-arrow next" aria-label="Next design">›</button></div><div class="gallery-strip" aria-label="${items.length} ${escapeHtml(p.category)} designs">${items.map((item,index)=>`<button class="gallery-thumb ${index===active?'active':''}" data-gallery-index="${index}" aria-label="Show ${escapeHtml(item.name)}" style="${cropStyle(item)}"></button>`).join('')}</div><div class="detail-content"><p class="eyebrow">${escapeHtml(p.category)} · ${active+1} of ${items.length}</p><h2>${escapeHtml(p.name)}</h2><p>Production estimate: ${p.days}<br>${p.bulk?'Bulk orders available':'Individual custom orders available'}</p><p>We can customize fabric, dimensions, thread colours and motif placement for your order.</p><a class="button primary" target="_blank" rel="noopener" href="https://wa.me/${phone}?text=${msg}">Enquire on WhatsApp</a></div>`;detail.querySelector('.previous').onclick=()=>{active=(active+items.length-1)%items.length;renderDetail()};detail.querySelector('.next').onclick=()=>{active=(active+1)%items.length;renderDetail()};detail.querySelectorAll('[data-gallery-index]').forEach(b=>b.onclick=()=>{active=Number(b.dataset.galleryIndex);renderDetail()})}renderDetail();document.querySelector('#productDialog').showModal()}
grid.addEventListener('click',e=>{const c=e.target.closest('[data-id]');if(c)openProduct(c.dataset.id)});grid.addEventListener('keydown',e=>{if((e.key==='Enter'||e.key===' ')&&e.target.dataset.id){e.preventDefault();openProduct(e.target.dataset.id)}});
document.querySelector('.dialog-close').onclick=()=>document.querySelector('#productDialog').close();document.querySelector('#productDialog').addEventListener('click',e=>{if(e.target.id==='productDialog')e.target.close()});
document.querySelector('#checkPincode').onclick=()=>{const v=document.querySelector('#pincode').value.trim(),r=document.querySelector('#pincodeResult');if(!/^\d{6}$/.test(v)){r.textContent='Please enter a valid 6-digit pincode.';r.className='error';return}r.textContent=`Thanks! Contact our team to confirm service and delivery for ${v}.`;r.className=''};
document.querySelector('#bulkForm').onsubmit=e=>{e.preventDefault();const d=new FormData(e.target),msg=`Hello Sundar Embroidery Works, I need a bulk quote.\nProduct: ${d.get('productType')}\nQuantity: ${d.get('quantity')}\nName: ${d.get('name')}\nMobile: ${d.get('mobile')}\nPincode: ${d.get('deliveryPincode')}\nRequired date: ${d.get('requiredDate')}\nRequirements: ${d.get('requirements')||'Not specified'}`;window.open(`https://wa.me/${phone}?text=${encodeURIComponent(msg)}`,'_blank','noopener')};
document.querySelector('#trackButton').onclick=()=>{const v=document.querySelector('#orderNumber').value.trim(),r=document.querySelector('#trackResult');if(!v){r.innerHTML='<p class="error">Please enter your order number.</p>';return}r.innerHTML=`<p class="notice">Demo tracking for <b>${v}</b></p><div class="timeline"><span class="done">Order confirmed</span><span class="done">Design finalized</span><span>In production</span><span>Quality check</span><span>Ready / dispatched</span><span>Delivered</span></div>`};
document.querySelector('#year').textContent=new Date().getFullYear();renderFilters();renderProducts();async function loadPublishedDesigns(){
  try {
    const saved=await window.SundarDesignStore.list();
    products.splice(0,products.length,...saved.filter(p=>p.published).map(p=>({...p,price:new Intl.NumberFormat('en-IN',{style:'currency',currency:'INR'}).format(p.price),days:'Request delivery estimate',bulk:false})),...demoData.products);
    renderProducts();
  } catch {
    const notice=document.createElement('p');notice.setAttribute('role','alert');notice.textContent='Saved designs could not be loaded. Refresh to try again.';grid.before(notice);
  }
}
void loadPublishedDesigns();
window.addEventListener('pageshow',event=>{if(event.persisted)void loadPublishedDesigns()});
if('serviceWorker'in navigator){
  let refreshed=false;
  navigator.serviceWorker.addEventListener('controllerchange',()=>{if(!refreshed){refreshed=true;location.reload()}});
  navigator.serviceWorker.register('sw.js',{updateViaCache:'none'}).then(registration=>registration.update()).catch(()=>{});
}


